enum NetworkError: Error {
    case offline(String)
    case badStatus(Int)
}

func retry(times: Int, _ load: () throws -> String) throws -> String {
    guard times > 0 else {
        throw NetworkError.offline("no more retries")
    }
    for attempt in 1...times {
        do {
            return try load()
        } catch {
            print("Attempt \(attempt) failed")
        }
    }
    throw NetworkError.offline("no more retries")
}

func firstMatch<T>(in values: [T], where predicate: (T) throws -> Bool) rethrows -> T? {
    for value in values {
        if try predicate(value) {
            return value
        }
    }
    return nil
}

