    var hasError = false
    var pending: Operation?
    var leftOperand: Double?
    private var isTyping = false

    var value: Double {
        Double(display) ?? 0
    }

    mutating func enter(_ digit: Int) {
        guard !hasError else { return }
        if isTyping && display != "0" {
            let signless = display.hasPrefix("-") ? String(display.dropFirst()) : display
            let whole = signless.prefix { $0 != "." }
            guard whole.count < Calculator.maxDigits else { return }
            display.append(String(digit))
        } else {
            let sign = display == "0" ? "" : (display.hasPrefix("-") ? "-" : "")
            display = sign + String(digit)
            isTyping = true
        }
    }
}

extension Calculator {
    mutating func clearAll() {
        display = "0"
        hasError = false
        pending = nil
        leftOperand = nil
        isTyping = false
    }

