            isTyping = true
        } else if !display.contains(".") {
            display.append(".")
        }
    }

    var formattedDisplay: String {
        if hasError {
            return display
        }
        let parts = display.split(separator: ".", maxSplits: 1)
        let whole = String(parts[0])
        let isNegative = whole.hasPrefix("-")
        let digits = isNegative ? String(whole.dropFirst()) : whole
        var grouped = ""
        for (offset, digit) in digits.enumerated() {
            if offset > 0 && (digits.count - offset) % 3 == 0 {
                grouped.append(Character(","))
            }
            grouped.append(digit)
        }
        let signed = isNegative ? "-" + grouped : grouped
        return parts.count == 2 ? signed + "." + String(parts[1]) : signed
    }
}

