import XCTest

@testable import Calculator

final class CalculatorTests: XCTestCase {
    func testEnteringDigitsReplacesTheStartingZero() {
        var calculator = Calculator()
        calculator.enter(7)
        XCTAssertEqual(calculator.display, "7")
        calculator.enter(5)
        XCTAssertEqual(calculator.display, "75")
    }

    func testEnteringZeroTwiceStaysAtZero() {
        var calculator = Calculator()
        calculator.enter(0)
        calculator.enter(0)
        XCTAssertEqual(calculator.display, "0")
    }

    func testTheNinthDigitIsTheLastOne() {
        var calculator = Calculator()
        for digit in [1, 2, 3, 4, 5, 6, 7, 8, 9, 9, 9] {
            calculator.enter(digit)
        }
        XCTAssertEqual(calculator.display, "123456789")
    }

    func testOnlyOneDecimalSeparatorIsKept() {
        var calculator = Calculator()
        calculator.enter(1)
        calculator.enterDecimalSeparator()
        calculator.enter(5)
        calculator.enterDecimalSeparator()
        XCTAssertEqual(calculator.display, "1.5")
    }

    func testTheSeparatorStartsAFreshNumber() {
        var calculator = Calculator()
        calculator.enterDecimalSeparator()
        XCTAssertEqual(calculator.display, "0.")
    }

    func testEqualsAppliesThePendingOperation() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.choose(.add)
        calculator.enter(3)
        calculator.equals()
        XCTAssertEqual(calculator.display, "5")
    }

    func testSubtractMultiplyAndDivide() {
        var calculator = Calculator()
        calculator.enter(9)
        calculator.choose(.subtract)
        calculator.enter(4)
        calculator.equals()
        XCTAssertEqual(calculator.display, "5")

        calculator.enter(6)
        calculator.choose(.multiply)
        calculator.enter(7)
        calculator.equals()
        XCTAssertEqual(calculator.display, "42")

        calculator.enter(8)
        calculator.choose(.divide)
        calculator.enter(2)
        calculator.equals()
        XCTAssertEqual(calculator.display, "4")
    }

    func testDivisionByZeroShowsAnErrorAndLocksTheKeys() {
        var calculator = Calculator()
        calculator.enter(8)
        calculator.choose(.divide)
        calculator.enter(0)
        calculator.equals()
        XCTAssertEqual(calculator.display, Calculator.errorText)
        XCTAssertTrue(calculator.hasError)
        calculator.enter(5)
        XCTAssertEqual(calculator.display, Calculator.errorText)
    }

    func testOperatorsChainLeftToRight() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.choose(.add)
        calculator.enter(3)
        calculator.choose(.multiply)
        XCTAssertEqual(calculator.display, "5")
        calculator.enter(4)
        calculator.equals()
        XCTAssertEqual(calculator.display, "20")
    }

    func testChoosingAnotherOperatorReplacesThePendingOne() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.choose(.add)
        calculator.choose(.multiply)
        calculator.enter(3)
        calculator.equals()
        XCTAssertEqual(calculator.display, "6")
    }

    func testNegatingTwiceReturnsTheOriginal() {
        var calculator = Calculator()
        calculator.enter(4)
        calculator.negate()
        XCTAssertEqual(calculator.display, "-4")
        calculator.negate()
        XCTAssertEqual(calculator.display, "4")
    }

    func testPercentDividesByOneHundred() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.enter(5)
        calculator.percent()
        XCTAssertEqual(calculator.display, "0.25")
    }

    func testClearEntryKeepsThePendingOperation() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.choose(.add)
        calculator.enter(9)
        calculator.clearEntry()
        XCTAssertEqual(calculator.display, "0")
        calculator.enter(3)
        calculator.equals()
        XCTAssertEqual(calculator.display, "5")
    }

    func testLargeProductsDoNotFallBackToScientificNotation() {
        var calculator = Calculator()
        for digit in [9, 9, 9, 9, 9, 9, 9, 9, 9] {
            calculator.enter(digit)
        }
        calculator.choose(.multiply)
        for digit in [9, 9, 9, 9, 9, 9, 9, 9, 9] {
            calculator.enter(digit)
        }
        calculator.equals()
        XCTAssertFalse(calculator.display.contains("e"))
        XCTAssertEqual(calculator.display.count, 18)
    }

    func testClearAllForgetsEverything() {
        var calculator = Calculator()
        calculator.enter(2)
        calculator.choose(.add)
        calculator.clearAll()
        XCTAssertEqual(calculator.display, "0")
        XCTAssertNil(calculator.pending)
        XCTAssertNil(calculator.leftOperand)
        XCTAssertFalse(calculator.hasError)
    }

    func testFormattedDisplayGroupsThousands() {
        var calculator = Calculator()
        for digit in [1, 2, 3, 4, 5, 6, 7] {
            calculator.enter(digit)
        }
        XCTAssertEqual(calculator.display, "1234567")
        XCTAssertEqual(calculator.formattedDisplay, "1,234,567")
    }

    func testFormattedDisplayKeepsTheDecimalPart() {
        var calculator = Calculator()
        for digit in [1, 2, 3, 4, 5, 6, 7] {
            calculator.enter(digit)
        }
        calculator.enterDecimalSeparator()
        calculator.enter(2)
        XCTAssertEqual(calculator.formattedDisplay, "1,234,567.2")
    }

    func testFormattedDisplayKeepsTheSignOutsideTheGrouping() {
        var calculator = Calculator()
        for digit in [1, 2, 3, 4, 5, 6, 7] {
            calculator.enter(digit)
        }
        calculator.negate()
        XCTAssertEqual(calculator.formattedDisplay, "-1,234,567")
    }

    func testTypingAfterNegatingStartsANewNumber() {
        var calculator = Calculator()
        calculator.enter(5)
        calculator.negate()
        calculator.enter(3)
        XCTAssertEqual(calculator.display, "-3")
    }
}

